class CheckoutFacade {
  async placeOrder(cart: Cart) {
    await InventoryService.reserve(cart.items);
    const price = PricingEngine.calculate(cart);
    const tax = TaxCalculator.compute(price, cart.region);
    await PaymentGateway.charge(price + tax);
    await EmailService.sendReceipt(cart.customerEmail, price + tax);
  }
}

// Every call site becomes one line — the order is now encapsulated
